// HIA Theme Builder 生成 — {{meta:name}}（vitepress-docs.tdon.json）
// Generated by HIA Theme Builder — target: VitePress docs site.
// 用法 / Usage:
//   1) 站点尚无主题扩展：直接使用本文件（npm create vitepress 默认 srcDir=docs）。
//   2) 已有 .vitepress/theme/index.ts：把下面 import './custom.css' 一行并入现有入口。
import DefaultTheme from 'vitepress/theme';
import './custom.css';

export default DefaultTheme;

/* HIA Theme Builder 生成 — {{meta:name}}（目标：VitePress 文档站）
   Generated by HIA Theme Builder — target: VitePress docs site.
   HIA → VitePress 默认主题变量全覆盖（亮 / 暗两段）。
   Full HIA → VitePress default-theme variable mapping, light & dark.
   变量语义核对自官方 vars.css（vuejs/vitepress，2026-11 取得）。
   画布（--vp-c-bg）保持 VitePress 原生值，仅着色功能层。安装见 HIA-THEME-INSTALL.md。 */

/* ===== 亮色（light）===== */
:root {
  color-scheme: light;

  /* 品牌色 brand：1=实色文本 / 2=hover / 3=实色底 / soft=浅底 */
  --vp-c-brand-1: {{token:primary.600}};
  --vp-c-brand-2: {{token:primary.700}};
  --vp-c-brand-3: {{token:primary.500}};
  --vp-c-brand-soft: {{token:primary.100}};
  --vp-c-brand: {{token:primary.600}};

  /* 画布与层次 bg：侧栏 / 代码块 / 组件浅底着主色最浅档 */
  --vp-c-bg-alt: {{token:primary.50}};
  --vp-c-bg-soft: {{token:primary.50}};

  /* 文本层级 text */
  --vp-c-text-1: {{token:primary.900}};
  --vp-c-text-2: {{token:primary.700}};
  --vp-c-text-3: {{token:primary.500}};

  /* 边线 border / divider / gutter */
  --vp-c-border: {{token:primary.200}};
  --vp-c-divider: {{token:primary.100}};
  --vp-c-gutter: {{token:primary.100}};

  /* 代码 code */
  --vp-code-color: {{token:primary.700}};
  --vp-code-bg: {{token:primary.50}};
  --vp-code-block-color: {{token:primary.900}};
  --vp-code-block-bg: {{token:primary.50}};
  --vp-code-lang-color: {{token:primary.500}};
  --vp-code-line-highlight-color: {{token:primary.100}};
  --vp-code-line-number-color: {{token:primary.300}};

  /* 语义提示容器 custom blocks：tip→success / info,note→info / important→primary /
     warning,caution→warning / danger→danger / details→中性 */
  --vp-custom-block-info-border: var(--hia-info-300, {{token:primary.300}});
  --vp-custom-block-info-text: var(--hia-info-800, {{token:primary.800}});
  --vp-custom-block-info-bg: var(--hia-info-50, {{token:primary.50}});
  --vp-custom-block-note-border: var(--hia-info-300, {{token:primary.300}});
  --vp-custom-block-note-text: var(--hia-info-800, {{token:primary.800}});
  --vp-custom-block-note-bg: var(--hia-info-50, {{token:primary.50}});
  --vp-custom-block-tip-border: var(--hia-success-300, {{token:primary.300}});
  --vp-custom-block-tip-text: var(--hia-success-800, {{token:primary.800}});
  --vp-custom-block-tip-bg: var(--hia-success-50, {{token:primary.50}});
  --vp-custom-block-important-border: {{token:primary.300}};
  --vp-custom-block-important-text: {{token:primary.800}};
  --vp-custom-block-important-bg: {{token:primary.50}};
  --vp-custom-block-warning-border: var(--hia-warning-300, {{token:primary.300}});
  --vp-custom-block-warning-text: var(--hia-warning-800, {{token:primary.800}});
  --vp-custom-block-warning-bg: var(--hia-warning-50, {{token:primary.50}});
  --vp-custom-block-caution-border: var(--hia-warning-300, {{token:primary.300}});
  --vp-custom-block-caution-text: var(--hia-warning-800, {{token:primary.800}});
  --vp-custom-block-caution-bg: var(--hia-warning-50, {{token:primary.50}});
  --vp-custom-block-danger-border: var(--hia-danger-300, {{token:primary.300}});
  --vp-custom-block-danger-text: var(--hia-danger-800, {{token:primary.800}});
  --vp-custom-block-danger-bg: var(--hia-danger-50, {{token:primary.50}});
  --vp-custom-block-details-border: {{token:primary.200}};
  --vp-custom-block-details-text: {{token:primary.800}};
  --vp-custom-block-details-bg: {{token:primary.50}};

  /* 按钮 brand */
  --vp-button-brand-border: {{token:primary.600}};
  --vp-button-brand-text: {{token:on:primary}};
  --vp-button-brand-bg: {{token:primary.600}};
  --vp-button-brand-hover-border: {{token:primary.700}};
  --vp-button-brand-hover-text: {{token:on:primary}};
  --vp-button-brand-hover-bg: {{token:primary.700}};
  --vp-button-brand-active-border: {{token:primary.800}};
  --vp-button-brand-active-text: {{token:on:primary}};
  --vp-button-brand-active-bg: {{token:primary.800}};

  /* 首页 Hero 渐变标题（VitePress 以 background-clip:text 渲染） */
  --vp-home-hero-name-color: transparent;
  --vp-home-hero-name-background: {{token:gradient:carousel}};

  /* 布局面板 layout */
  --vp-sidebar-bg-color: {{token:primary.50}};
  --vp-nav-bg-color: {{token:primary.50}};

  /* 徽章 badges */
  --vp-badge-info-border: var(--hia-info-300, {{token:primary.300}});
  --vp-badge-info-text: var(--hia-info-800, {{token:primary.800}});
  --vp-badge-info-bg: var(--hia-info-50, {{token:primary.50}});
  --vp-badge-tip-border: var(--hia-success-300, {{token:primary.300}});
  --vp-badge-tip-text: var(--hia-success-800, {{token:primary.800}});
  --vp-badge-tip-bg: var(--hia-success-50, {{token:primary.50}});
  --vp-badge-warning-border: var(--hia-warning-300, {{token:primary.300}});
  --vp-badge-warning-text: var(--hia-warning-800, {{token:primary.800}});
  --vp-badge-warning-bg: var(--hia-warning-50, {{token:primary.50}});
  --vp-badge-danger-border: var(--hia-danger-300, {{token:primary.300}});
  --vp-badge-danger-text: var(--hia-danger-800, {{token:primary.800}});
  --vp-badge-danger-bg: var(--hia-danger-50, {{token:primary.50}});

  /* 字体族（覆盖默认捆绑的 Inter） */
  --vp-font-family-base: {{token:font:body}};
  --vp-font-family-mono: {{token:font:mono}};
}

/* ===== 暗色（dark，html.dark 由 VitePress 明暗切换挂载）===== */
html.dark {
  color-scheme: dark;

  --vp-c-brand-1: {{token:primary.300}};
  --vp-c-brand-2: {{token:primary.200}};
  --vp-c-brand-3: {{token:primary.400}};
  --vp-c-brand-soft: {{token:primary.800}};
  --vp-c-brand: {{token:primary.300}};

  --vp-c-bg-alt: {{token:primary.950}};
  --vp-c-bg-elv: {{token:primary.900}};
  --vp-c-bg-soft: {{token:primary.900}};

  --vp-c-text-1: {{token:primary.100}};
  --vp-c-text-2: {{token:primary.200}};
  --vp-c-text-3: {{token:primary.300}};

  --vp-c-border: {{token:primary.700}};
  --vp-c-divider: {{token:primary.800}};
  --vp-c-gutter: {{token:primary.800}};

  --vp-code-color: {{token:primary.300}};
  --vp-code-bg: {{token:primary.900}};
  --vp-code-block-color: {{token:primary.100}};
  --vp-code-block-bg: {{token:primary.950}};
  --vp-code-lang-color: {{token:primary.400}};
  --vp-code-line-highlight-color: {{token:primary.900}};
  --vp-code-line-number-color: {{token:primary.600}};

  --vp-custom-block-info-border: var(--hia-info-700, {{token:primary.700}});
  --vp-custom-block-info-text: var(--hia-info-200, {{token:primary.200}});
  --vp-custom-block-info-bg: var(--hia-info-950, {{token:primary.950}});
  --vp-custom-block-note-border: var(--hia-info-700, {{token:primary.700}});
  --vp-custom-block-note-text: var(--hia-info-200, {{token:primary.200}});
  --vp-custom-block-note-bg: var(--hia-info-950, {{token:primary.950}});
  --vp-custom-block-tip-border: var(--hia-success-700, {{token:primary.700}});
  --vp-custom-block-tip-text: var(--hia-success-200, {{token:primary.200}});
  --vp-custom-block-tip-bg: var(--hia-success-950, {{token:primary.950}});
  --vp-custom-block-important-border: {{token:primary.700}};
  --vp-custom-block-important-text: {{token:primary.200}};
  --vp-custom-block-important-bg: {{token:primary.950}};
  --vp-custom-block-warning-border: var(--hia-warning-700, {{token:primary.700}});
  --vp-custom-block-warning-text: var(--hia-warning-200, {{token:primary.200}});
  --vp-custom-block-warning-bg: var(--hia-warning-950, {{token:primary.950}});
  --vp-custom-block-caution-border: var(--hia-warning-700, {{token:primary.700}});
  --vp-custom-block-caution-text: var(--hia-warning-200, {{token:primary.200}});
  --vp-custom-block-caution-bg: var(--hia-warning-950, {{token:primary.950}});
  --vp-custom-block-danger-border: var(--hia-danger-700, {{token:primary.700}});
  --vp-custom-block-danger-text: var(--hia-danger-200, {{token:primary.200}});
  --vp-custom-block-danger-bg: var(--hia-danger-950, {{token:primary.950}});
  --vp-custom-block-details-border: {{token:primary.700}};
  --vp-custom-block-details-text: {{token:primary.200}};
  --vp-custom-block-details-bg: {{token:primary.950}};

  --vp-button-brand-border: {{token:primary.400}};
  --vp-button-brand-text: {{token:on:primary}};
  --vp-button-brand-bg: {{token:primary.400}};
  --vp-button-brand-hover-border: {{token:primary.300}};
  --vp-button-brand-hover-text: {{token:on:primary}};
