  --vp-home-hero-name-color: transparent;
  --vp-home-hero-name-background: {{token:gradient:carousel}};

  --vp-sidebar-bg-color: {{token:primary.950}};
  --vp-nav-bg-color: {{token:primary.950}};

  --vp-badge-info-border: var(--hia-info-700, {{token:primary.700}});
  --vp-badge-info-text: var(--hia-info-200, {{token:primary.200}});
  --vp-badge-info-bg: var(--hia-info-950, {{token:primary.950}});
